/**
 * Generate routes for ALL questions — existing orphans + new questions.
 *
 * Memory-efficient: only loads question metadata (small), processes routes
 * in tag cohorts, reads/writes route files one at a time instead of holding
 * all in memory.
 *
 * Route types generated:
 * - expansion: shared tags, lower → higher abstraction
 * - domain-crossing: shared tags, different semantic types
 * - synonym: same type, similar level, high tag overlap
 * - contradiction: opposition tag pairs
 */

import fs from "fs";
import path from "path";
import { Question, Route, RouteFile } from "../src/lib/types";

const questionsDir = path.join(process.cwd(), "data", "questions");
const routesDir = path.join(process.cwd(), "data", "routes");

// ── Config ──

const MAX_ROUTES_PER_TYPE = 15;
const MAX_COHORT_SIZE = 300; // skip tags with more questions than this

// ── Load questions as lightweight objects ──

interface QuestionMeta {
  id: string;
  semanticType: string;
  abstractionLevel: number;
  tags: string[];
}

console.log("Loading question metadata...");
const files = fs.readdirSync(questionsDir).filter((f) => f.endsWith(".json"));
const questions: QuestionMeta[] = [];
const questionIndex = new Map<string, QuestionMeta>();

for (const f of files) {
  try {
    const raw = fs.readFileSync(path.join(questionsDir, f), "utf-8");
    const q = JSON.parse(raw) as Question;
    const meta: QuestionMeta = {
      id: q.id,
      semanticType: q.semanticType,
      abstractionLevel: q.abstractionLevel,
      tags: q.tags,
    };
    questions.push(meta);
    questionIndex.set(q.id, meta);
  } catch {
    // skip
  }
}
console.log(`  Loaded ${questions.length} questions`);

// ── Index by tag ──

console.log("Building tag index...");
const questionsByTag = new Map<string, string[]>();

for (const q of questions) {
  for (const tag of q.tags) {
    if (tag === "general") continue;
    if (!questionsByTag.has(tag)) questionsByTag.set(tag, []);
    questionsByTag.get(tag)!.push(q.id);
  }
}

// Remove overly common tags
let skippedTags = 0;
for (const [tag, ids] of questionsByTag) {
  if (ids.length > MAX_COHORT_SIZE) {
    questionsByTag.delete(tag);
    skippedTags++;
  }
}
console.log(`  ${questionsByTag.size} tags indexed (${skippedTags} skipped as too common)`);

// ── Route file helpers (read/write one at a time) ──

function readRouteFile(sourceId: string): RouteFile {
  const filePath = path.join(routesDir, `${sourceId}.json`);
  if (fs.existsSync(filePath)) {
    return JSON.parse(fs.readFileSync(filePath, "utf-8")) as RouteFile;
  }
  return { sourceId, routes: [] };
}

function writeRouteFile(rf: RouteFile) {
  if (rf.routes.length === 0) return;
  const filePath = path.join(routesDir, `${rf.sourceId}.json`);
  fs.writeFileSync(filePath, JSON.stringify(rf, null, 2) + "\n", "utf-8");
}

function hasRoute(rf: RouteFile, targetId: string, type: string): boolean {
  return rf.routes.some((r) => r.targetId === targetId && r.type === type);
}

function countRoutesOfType(rf: RouteFile, type: string): number {
  return rf.routes.filter((r) => r.type === type).length;
}

function tryAddRoute(rf: RouteFile, route: Route): boolean {
  if (rf.sourceId === route.targetId) return false;
  if (hasRoute(rf, route.targetId, route.type)) return false;
  if (countRoutesOfType(rf, route.type) >= MAX_ROUTES_PER_TYPE) return false;
  rf.routes.push(route);
  return true;
}

// Batch: accumulate pending routes keyed by sourceId, flush periodically
const pendingRoutes = new Map<string, Route[]>();
let pendingCount = 0;
const FLUSH_THRESHOLD = 5000;

function queueRoute(sourceId: string, route: Route): boolean {
  if (sourceId === route.targetId) return false;
  if (!pendingRoutes.has(sourceId)) pendingRoutes.set(sourceId, []);
  pendingRoutes.get(sourceId)!.push(route);
  pendingCount++;
  return true;
}

function flushPending() {
  if (pendingCount === 0) return;
  let written = 0;
  let added = 0;

  for (const [sourceId, routes] of pendingRoutes) {
    const rf = readRouteFile(sourceId);
    for (const route of routes) {
      if (tryAddRoute(rf, route)) {
        added++;
      }
    }
    writeRouteFile(rf);
    written++;
  }

  console.log(`  Flushed: ${written} files, ${added} routes added`);
  pendingRoutes.clear();
  pendingCount = 0;
  return added;
}

// ── Stats ──

const stats: Record<string, number> = {};

function track(type: string) {
  stats[type] = (stats[type] || 0) + 1;
}

// ── 1. Expansion + domain-crossing (tag-cohort based) ──

console.log("\nProcessing tag cohorts for expansion + domain-crossing...");
let cohortsDone = 0;
const totalCohorts = questionsByTag.size;

for (const [tag, ids] of questionsByTag) {
  for (let i = 0; i < ids.length; i++) {
    const a = questionIndex.get(ids[i])!;
    for (let j = i + 1; j < ids.length; j++) {
      const b = questionIndex.get(ids[j])!;

      const sharedTags = a.tags.filter((t) => t !== "general" && b.tags.includes(t));

      // Expansion: different abstraction levels
      if (a.abstractionLevel !== b.abstractionLevel && sharedTags.length >= 1) {
        const [lower, higher] = a.abstractionLevel < b.abstractionLevel ? [a, b] : [b, a];
        const weight = sharedTags.length >= 3 ? "high" : sharedTags.length >= 2 ? "medium" : "low";

        queueRoute(lower.id, {
          targetId: higher.id,
          type: "expansion",
          reason: `Expands via: ${sharedTags.slice(0, 3).join(", ")}`,
          weight,
        });
        track("expansion");
      }

      // Domain-crossing: different semantic types, 2+ shared tags
      if (a.semanticType !== b.semanticType
          && a.semanticType !== "general" && b.semanticType !== "general"
          && sharedTags.length >= 2) {
        const weight = sharedTags.length >= 3 ? "high" : "medium";

        queueRoute(a.id, {
          targetId: b.id,
          type: "domain-crossing",
          reason: `${a.semanticType} → ${b.semanticType}: ${sharedTags.slice(0, 3).join(", ")}`,
          weight,
        });
        track("domain-crossing");
      }
    }
  }

  cohortsDone++;
  if (pendingCount >= FLUSH_THRESHOLD) {
    console.log(`  [${cohortsDone}/${totalCohorts}] Flushing...`);
    flushPending();
  }
}
flushPending();

// ── 2. Synonym routes (tag-cohort based) ──

console.log("\nProcessing tag cohorts for synonyms...");

for (const [tag, ids] of questionsByTag) {
  for (let i = 0; i < ids.length; i++) {
    const a = questionIndex.get(ids[i])!;
    for (let j = i + 1; j < ids.length; j++) {
      const b = questionIndex.get(ids[j])!;
      if (a.semanticType !== b.semanticType) continue;
      if (Math.abs(a.abstractionLevel - b.abstractionLevel) > 1) continue;

      const sharedTags = a.tags.filter((t) => t !== "general" && b.tags.includes(t));
      const allTags = new Set([...a.tags, ...b.tags].filter((t) => t !== "general"));
      if (allTags.size === 0) continue;

      const overlap = sharedTags.length / allTags.size;
      if (overlap < 0.5 || sharedTags.length < 2) continue;

      const weight = overlap >= 0.8 ? "high" : "medium";

      queueRoute(a.id, {
        targetId: b.id,
        type: "synonym",
        reason: `${Math.round(overlap * 100)}% tag overlap`,
        weight,
      });
      queueRoute(b.id, {
        targetId: a.id,
        type: "synonym",
        reason: `${Math.round(overlap * 100)}% tag overlap`,
        weight,
      });
      track("synonym");
      track("synonym");
    }
  }

  if (pendingCount >= FLUSH_THRESHOLD) {
    flushPending();
  }
}
flushPending();

// ── 3. Contradiction routes (opposition pairs) ──

console.log("\nGenerating contradiction routes...");

const oppositionPairs: [string, string][] = [
  ["totality", "nothing"],
  ["presence", "absence"],
  ["beginning", "ending"],
  ["internal", "external"],
  ["certainty", "uncertainty"],
  ["action", "passivity"],
  ["unity", "plurality"],
  ["finite", "infinite"],
  ["permanence", "impermanence"],
  ["freedom", "constraint"],
  ["creation", "destruction"],
  ["order", "chaos"],
  ["simplicity", "complexity"],
  ["independence", "dependence"],
  ["movement", "stillness"],
  ["continuity", "discontinuity"],
  ["surface", "depth"],
  ["appearance", "reality"],
  ["known", "unknown"],
  ["subjective", "objective"],
  ["particular", "universal"],
  ["natural", "artificial"],
  ["individual", "collective"],
  ["visible", "invisible"],
  ["temporal", "eternal"],
  ["material", "immaterial"],
];

for (const [tagA, tagB] of oppositionPairs) {
  const groupA = questionsByTag.get(tagA) || [];
  const groupB = questionsByTag.get(tagB) || [];

  for (const idA of groupA) {
    for (const idB of groupB) {
      if (idA === idB) continue;
      queueRoute(idA, {
        targetId: idB,
        type: "contradiction",
        reason: `${tagA} ↔ ${tagB}`,
        weight: "medium",
      });
      track("contradiction");
    }
  }
}
flushPending();

// ── Summary ──

// Count orphans
console.log("\nCounting orphans...");
const routeFileList = fs.readdirSync(routesDir).filter((f) => f.endsWith(".json"));
const questionsWithRoutes = new Set<string>();
for (const f of routeFileList) {
  const sourceId = f.replace(".json", "");
  questionsWithRoutes.add(sourceId);
  try {
    const raw = fs.readFileSync(path.join(routesDir, f), "utf-8");
    const rf = JSON.parse(raw) as RouteFile;
    for (const r of rf.routes) {
      questionsWithRoutes.add(r.targetId);
    }
  } catch {}
}

const orphanCount = questions.filter((q) => !questionsWithRoutes.has(q.id)).length;

console.log(`\n${"=".repeat(50)}`);
console.log("Route generation complete:");
console.log(`  Total questions: ${questions.length}`);
console.log(`  Route files: ${routeFileList.length}`);
console.log(`  Orphans remaining: ${orphanCount} / ${questions.length}`);
console.log("\nRoutes queued by type:");
for (const [type, count] of Object.entries(stats).sort((a, b) => b[1] - a[1])) {
  console.log(`  ${type}: ${count}`);
}

/**
 * Phase 2: Generate new route types for existing questions.
 *
 * New route types: abstraction, concretization, contradiction, negation,
 * decomposition, synonym, domain-crossing, temporal
 *
 * Appends to existing route files or creates new ones.
 */

import fs from "fs";
import path from "path";
import { Question, Route, RouteFile } from "../src/lib/types";
import { getAllQuestions, getRoutesFrom } from "../src/lib/data";

const routesDir = path.join(process.cwd(), "data", "routes");

// ── helpers ──

function readRouteFile(sourceId: string): RouteFile {
  const filePath = path.join(routesDir, `${sourceId}.json`);
  if (fs.existsSync(filePath)) {
    return JSON.parse(fs.readFileSync(filePath, "utf-8")) as RouteFile;
  }
  return { sourceId, routes: [] };
}

function writeRouteFile(rf: RouteFile) {
  const filePath = path.join(routesDir, `${rf.sourceId}.json`);
  fs.writeFileSync(filePath, JSON.stringify(rf, null, 2) + "\n", "utf-8");
}

function hasRoute(rf: RouteFile, targetId: string, type: string): boolean {
  return rf.routes.some((r) => r.targetId === targetId && r.type === type);
}

function addRoute(rf: RouteFile, route: Route): boolean {
  if (rf.sourceId === route.targetId) return false;
  if (hasRoute(rf, route.targetId, route.type)) return false;
  rf.routes.push(route);
  return true;
}

// ── load data ──

const questions = getAllQuestions();
const questionMap = new Map(questions.map((q) => [q.id, q]));
const questionsByTag = new Map<string, Question[]>();
const questionsByType = new Map<string, Question[]>();
const questionsByLevel = new Map<number, Question[]>();

for (const q of questions) {
  for (const tag of q.tags) {
    if (!questionsByTag.has(tag)) questionsByTag.set(tag, []);
    questionsByTag.get(tag)!.push(q);
  }
  if (!questionsByType.has(q.semanticType)) questionsByType.set(q.semanticType, []);
  questionsByType.get(q.semanticType)!.push(q);
  if (!questionsByLevel.has(q.abstractionLevel)) questionsByLevel.set(q.abstractionLevel, []);
  questionsByLevel.get(q.abstractionLevel)!.push(q);
}

let totalAdded = 0;
const modifiedFiles = new Set<string>();

// ── 1. Abstraction routes: lower → higher level with shared tags ──

console.log("Generating abstraction routes...");
let abstractionCount = 0;

for (const q of questions) {
  if (q.abstractionLevel >= 5) continue;
  const rf = readRouteFile(q.id);

  // Find questions at higher levels sharing tags
  for (let level = q.abstractionLevel + 1; level <= 5; level++) {
    const candidates = questionsByLevel.get(level) || [];
    for (const target of candidates) {
      const sharedTags = q.tags.filter((t) => target.tags.includes(t));
      if (sharedTags.length >= 2) {
        if (addRoute(rf, {
          targetId: target.id,
          type: "abstraction",
          reason: `Abstracts via shared concepts: ${sharedTags.slice(0, 3).join(", ")}`,
          weight: sharedTags.length >= 3 ? "high" : "medium",
        })) {
          abstractionCount++;
        }
      }
    }
  }

  if (rf.routes.length > 0) {
    writeRouteFile(rf);
    modifiedFiles.add(q.id);
  }
}
console.log(`  Added ${abstractionCount} abstraction routes`);
totalAdded += abstractionCount;

// ── 2. Concretization routes: higher → lower level with shared tags ──

console.log("Generating concretization routes...");
let concretizationCount = 0;

for (const q of questions) {
  if (q.abstractionLevel <= 0) continue;
  const rf = readRouteFile(q.id);

  for (let level = q.abstractionLevel - 1; level >= 0; level--) {
    const candidates = questionsByLevel.get(level) || [];
    for (const target of candidates) {
      const sharedTags = q.tags.filter((t) => target.tags.includes(t));
      if (sharedTags.length >= 2) {
        if (addRoute(rf, {
          targetId: target.id,
          type: "concretization",
          reason: `Concretizes via: ${sharedTags.slice(0, 3).join(", ")}`,
          weight: sharedTags.length >= 3 ? "high" : "medium",
        })) {
          concretizationCount++;
        }
      }
    }
  }

  writeRouteFile(rf);
  modifiedFiles.add(q.id);
}
console.log(`  Added ${concretizationCount} concretization routes`);
totalAdded += concretizationCount;

// ── 3. Contradiction routes: questions with opposition semantics ──

console.log("Generating contradiction routes...");
let contradictionCount = 0;

// Pairs of tags that represent oppositions
const oppositionPairs: [string, string][] = [
  ["totality", "nothing"],
  ["presence", "absence"],
  ["beginning", "ending"],
  ["internal", "external"],
  ["certainty", "uncertainty"],
  ["action", "passivity"],
  ["unity", "plurality"],
  ["finite", "infinite"],
  ["permanence", "impermanence"],
  ["freedom", "constraint"],
  ["creation", "destruction"],
  ["order", "chaos"],
  ["simplicity", "complexity"],
  ["independence", "dependence"],
  ["movement", "stillness"],
  ["continuity", "discontinuity"],
  ["surface", "depth"],
  ["appearance", "reality"],
  ["known", "unknown"],
];

for (const [tagA, tagB] of oppositionPairs) {
  const groupA = questionsByTag.get(tagA) || [];
  const groupB = questionsByTag.get(tagB) || [];

  for (const a of groupA) {
    for (const b of groupB) {
      if (a.id === b.id) continue;
      const rf = readRouteFile(a.id);
      if (addRoute(rf, {
        targetId: b.id,
        type: "contradiction",
        reason: `${tagA} contradicts ${tagB}`,
        weight: "medium",
      })) {
        contradictionCount++;
      }
      writeRouteFile(rf);
      modifiedFiles.add(a.id);
    }
  }
}
console.log(`  Added ${contradictionCount} contradiction routes`);
totalAdded += contradictionCount;

// ── 4. Negation routes: pair questions with their negation-tagged counterparts ──

console.log("Generating negation routes...");
let negationCount = 0;

// Find pairs where one question's text is the negation concept of another
const negationPairs: [string, string][] = [
  ["all", "none"],
  ["always", "never"],
  ["presence", "absence"],
  ["real", "illusion"],
  ["true", "false"],
  ["good", "bad"],
  ["more", "less"],
  ["beginning", "ending"],
  ["here", "there"],
  ["now", "then"],
  ["can", "must"],
  ["hope", "despair"],
  ["silence", "voice"],
  ["alone", "together"],
  ["simple", "form"],
  ["old", "new"],
  ["first", "last"],
];

for (const [idA, idB] of negationPairs) {
  const a = questionMap.get(idA);
  const b = questionMap.get(idB);
  if (!a || !b) continue;

  // A → B
  const rfA = readRouteFile(idA);
  if (addRoute(rfA, {
    targetId: idB,
    type: "negation",
    reason: `"${a.text}" negates "${b.text}"`,
    weight: "high",
  })) {
    negationCount++;
  }
  writeRouteFile(rfA);
  modifiedFiles.add(idA);

  // B → A
  const rfB = readRouteFile(idB);
  if (addRoute(rfB, {
    targetId: idA,
    type: "negation",
    reason: `"${b.text}" negates "${a.text}"`,
    weight: "high",
  })) {
    negationCount++;
  }
  writeRouteFile(rfB);
  modifiedFiles.add(idB);
}
console.log(`  Added ${negationCount} negation routes`);
totalAdded += negationCount;

// ── 5. Domain-crossing routes: questions sharing tags across different semantic types ──

console.log("Generating domain-crossing routes...");
let domainCrossingCount = 0;

for (const q of questions) {
  const rf = readRouteFile(q.id);

  for (const tag of q.tags) {
    const tagged = questionsByTag.get(tag) || [];
    for (const target of tagged) {
      if (target.id === q.id) continue;
      if (target.semanticType === q.semanticType) continue;

      // Only create domain-crossing for questions with 2+ shared tags but different types
      const sharedTags = q.tags.filter((t) => target.tags.includes(t));
      if (sharedTags.length >= 2) {
        if (addRoute(rf, {
          targetId: target.id,
          type: "domain-crossing",
          reason: `Crosses from ${q.semanticType} to ${target.semanticType} via: ${sharedTags.slice(0, 3).join(", ")}`,
          weight: sharedTags.length >= 3 ? "high" : "low",
        })) {
          domainCrossingCount++;
        }
      }
    }
  }

  writeRouteFile(rf);
  modifiedFiles.add(q.id);
}
console.log(`  Added ${domainCrossingCount} domain-crossing routes`);
totalAdded += domainCrossingCount;

// ── 6. Decomposition routes: compound-sounding questions to their components ──

console.log("Generating decomposition routes...");
let decompositionCount = 0;

// Questions with many tags likely decompose into questions with subsets of those tags
for (const q of questions) {
  if (q.tags.length < 3) continue;
  const rf = readRouteFile(q.id);

  for (const target of questions) {
    if (target.id === q.id) continue;
    if (target.abstractionLevel >= q.abstractionLevel) continue;

    // Target should share some but not all tags (a subset)
    const sharedTags = target.tags.filter((t) => q.tags.includes(t));
    const uniqueToTarget = target.tags.filter((t) => !q.tags.includes(t));

    if (sharedTags.length >= 1 && sharedTags.length < q.tags.length && uniqueToTarget.length <= 1) {
      if (addRoute(rf, {
        targetId: target.id,
        type: "decomposition",
        reason: `Decomposes into component: ${sharedTags.join(", ")}`,
        weight: "low",
      })) {
        decompositionCount++;
      }
    }
  }

  writeRouteFile(rf);
  modifiedFiles.add(q.id);
}
console.log(`  Added ${decompositionCount} decomposition routes`);
totalAdded += decompositionCount;

// ── 7. Synonym routes: questions with very similar tag sets ──

console.log("Generating synonym routes...");
let synonymCount = 0;

for (let i = 0; i < questions.length; i++) {
  const a = questions[i];
  const rf = readRouteFile(a.id);

  for (let j = i + 1; j < questions.length; j++) {
    const b = questions[j];
    if (a.semanticType !== b.semanticType) continue;
    if (Math.abs(a.abstractionLevel - b.abstractionLevel) > 1) continue;

    const sharedTags = a.tags.filter((t) => b.tags.includes(t));
    const totalTags = new Set([...a.tags, ...b.tags]).size;
    const overlap = sharedTags.length / totalTags;

    if (overlap >= 0.6 && sharedTags.length >= 2) {
      if (addRoute(rf, {
        targetId: b.id,
        type: "synonym",
        reason: `Near-synonym: same type (${a.semanticType}), ${Math.round(overlap * 100)}% tag overlap`,
        weight: overlap >= 0.8 ? "high" : "medium",
      })) {
        synonymCount++;
      }

      // Bidirectional
      const rfB = readRouteFile(b.id);
      if (addRoute(rfB, {
        targetId: a.id,
        type: "synonym",
        reason: `Near-synonym: same type (${b.semanticType}), ${Math.round(overlap * 100)}% tag overlap`,
        weight: overlap >= 0.8 ? "high" : "medium",
      })) {
        synonymCount++;
      }
      writeRouteFile(rfB);
      modifiedFiles.add(b.id);
    }
  }

  writeRouteFile(rf);
  modifiedFiles.add(a.id);
}
console.log(`  Added ${synonymCount} synonym routes`);
totalAdded += synonymCount;

// ── Summary ──

console.log(`\nPhase 2 complete:`);
console.log(`  Total new routes: ${totalAdded}`);
console.log(`  Modified files: ${modifiedFiles.size}`);

/**
 * Generate per-question JSON files for the /compare page's client-side fetching.
 */
import fs from "fs";
import path from "path";
import {
  getAllQuestions,
  getRoutesFrom,
  getRoutesTo,
  getChainsContaining,
  getSequencesThrough,
} from "../src/lib/data";

const outDir = path.join(process.cwd(), "public", "compare-data");
fs.mkdirSync(outDir, { recursive: true });

const questions = getAllQuestions();

for (const q of questions) {
  const outgoing = getRoutesFrom(q.id);
  const incoming = getRoutesTo(q.id);
  const chains = getChainsContaining(q.id);
  const sequences = getSequencesThrough(q.id);

  const data = {
    question: {
      id: q.id,
      text: q.text,
      definition: q.definition,
      semanticType: q.semanticType,
      abstractionLevel: q.abstractionLevel,
      tags: q.tags,
    },
    outgoing: outgoing.map((r) => ({
      targetId: r.targetId,
      type: r.type,
      reason: r.reason,
      weight: r.weight,
    })),
    incoming: incoming.map((r) => ({
      sourceId: r.sourceId,
      type: r.route.type,
    })),
    chains: chains.map((c) => ({
      id: c.id,
      composedText: c.composedText,
    })),
    sequences: sequences.map((s) => ({
      id: s.id,
      name: s.name,
    })),
  };

  fs.writeFileSync(
    path.join(outDir, `${q.id}.json`),
    JSON.stringify(data),
    "utf-8"
  );
}

console.log(`Generated compare data for ${questions.length} questions → ${outDir}`);
